  },
} as const satisfies Record<string, Record<Kind, string>>

export type ThemeName = keyof typeof THEMES

// Where a gradient label ends: each label fades from its kind's color to this.
export const GLOW: Readonly<Record<ThemeName, string>> = {
  ocean: '#E0F7FF',
  sunset: '#FFF1C1',
  neon: '#FFFFFF',
  forest: '#F0EAD2',
  claude: '#FBE9DF',
  aurora: '#F8F8F2',
  pastel: '#FFFFFF',
}

function rgb(hex: string): [number, number, number] {
  const n = Number.parseInt(hex.replace('#', ''), 16)
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255]
}

/** Each character of `text` with its color, fading from `from` to `to`. */
export function gradient(text: string, from: string, to: string): [string, string][] {
  const chars = [...text]
  const [a, b] = [rgb(from), rgb(to)]
  return chars.map((ch, i) => {
    const t = chars.length <= 1 ? 0 : i / (chars.length - 1)
    const mix = a.map((v, k) => Math.round(v + (b[k]! - v) * t))
    return [ch, `#${mix.map(v => v.toString(16).padStart(2, '0')).join('')}`]
  })
}

export const DEFAULT_STYLE: StyleName = 'circled'
export const DEFAULT_THEME: ThemeName = 'ocean'

export function isStyle(name: string): name is StyleName {
  return Object.hasOwn(STYLES, name)
}

export function isTheme(name: string): name is ThemeName {
  return Object.hasOwn(THEMES, name)
}

const READ = new Set(['Read', 'NotebookRead'])
const EDIT = new Set(['Edit', 'MultiEdit', 'NotebookEdit'])
const SEARCH = new Set(['Grep', 'Glob', 'ToolSearch', 'LSP', 'ListMcpResourcesTool'])
const WEB = new Set(['WebFetch', 'WebSearch'])
const AGENT = new Set(['Agent', 'Task', 'SendMessage', 'ListAgents', 'TaskStop', 'Workflow'])
const PLAN = new Set(['TodoWrite', 'TaskCreate', 'TaskUpdate', 'EnterPlanMode', 'ExitPlanMode', 'CronCreate', 'ScheduleWakeup'])
// A delete at a command position: start of line or after ; | & ( and spaces.
const DELETE_COMMAND = /(^|[;&|(]\s*|\bsudo\s+)(rm|rmdir|del|erase|rd|remove-item|ri)\b/im

const SHELLS = new Set(['Bash', 'PowerShell'])

function commandOf(input: unknown): string {
  const command = (input as { command?: unknown } | null)?.command
  return typeof command === 'string' ? command : ''
}

/** A WebSocket a tool watches (Monitor's `ws.url`), when it names one. */
function socketOf(input: unknown): string {
  const ws = (input as { ws?: { url?: unknown } } | null)?.ws
  return typeof ws?.url === 'string' ? ws.url : ''
}

export function kindOf(tool: string, input: unknown): Kind {
  // Any built-in tool that carries a shell command (Bash, PowerShell, Monitor)
  // is a shell row, so the row shows the command rather than prose about it.
  // An MCP tool keeps its server's name, whatever its fields are called.
  if (SHELLS.has(tool) || (!tool.startsWith('mcp__') && commandOf(input) !== '')) {
    return DELETE_COMMAND.test(commandOf(input).trim()) ? 'delete' : 'shell'
  }
  if (!tool.startsWith('mcp__') && socketOf(input) !== '') return 'web'
  if (READ.has(tool)) return 'read'
  if (EDIT.has(tool)) return 'edit'
  if (tool === 'Write') return 'write'
  if (SEARCH.has(tool)) return 'search'
  if (WEB.has(tool)) return 'web'
  if (AGENT.has(tool)) return 'agent'
  if (PLAN.has(tool)) return 'plan'
  if (tool === 'Skill') return 'skill'
  if (tool === 'AskUserQuestion') return 'ask'
  if (tool.startsWith('mcp__')) return 'mcp'
  return 'other'
}

/** `mcp__claude_ai_Example__search_records` → `Example · search_records`. */
export function mcpName(tool: string): string {
  const [, server = '', ...rest] = tool.split('__')
  const short = server.replace(/^claude_ai_/, '').replace(/^plugin_[^_]+_/, '')
  return `${short} · ${rest.join('__')}`
}

export function label(kind: Kind, tool: string): string {
  if (kind === 'mcp') return mcpName(tool)
  if (kind === 'other' || kind === 'agent' || kind === 'plan') return tool
  // a shell or web row from a tool other than the usual ones keeps its own name
  if ((kind === 'shell' || kind === 'delete') && !SHELLS.has(tool)) return tool
  if (kind === 'web' && !WEB.has(tool)) return tool
  return LABELS[kind]
}

/** Control and format characters (escapes, bidi overrides, zero-width marks) removed. */
export function printable(text: string): string {
  return text.replace(/[\p{Cc}\p{Cf}]/gu, '')
}

function field(input: unknown, ...names: string[]): string {
  const record = (input ?? {}) as Record<string, unknown>
  for (const name of names) {
    const value = record[name]
    if (typeof value === 'string' && value.trim() !== '') return value
  }
  return ''
}

/** A path relative to the session folder when it lies under it. */
export function shortPath(path: string, cwd: string): string {
  const norm = (p: string) => p.replace(/\\/g, '/').replace(/\/+$/, '')
  const p = norm(path)
  const root = norm(cwd)
  if (root !== '' && p.toLowerCase().startsWith(`${root.toLowerCase()}/`)) return p.slice(root.length + 1)
  return p
}

/** The few words after the label: a file, a command, a pattern, a query. */
export function target(tool: string, input: unknown, cwd: string): string {
  const kind = kindOf(tool, input)
  switch (kind) {
    case 'read':
    case 'edit':
    case 'write':
      return shortPath(field(input, 'file_path', 'notebook_path', 'path'), cwd)
    case 'shell':
    case 'delete': {
      // The command itself, never the model's own description of it: the row
      // is the record of what ran. A multi-line command says so up front,
      // where cutting the line to fit cannot hide it.
      const lines = commandOf(input).trim().split(/\r?\n/)
      return lines.length > 1 ? `(${lines.length} lines) ${lines[0]!.trim()}` : lines[0]!.trim()
    }
    case 'search':
      return field(input, 'pattern', 'query')
    case 'web': {
      const url = field(input, 'url') || socketOf(input)
      if (url !== '') {
        try {
          return new URL(url).host
        } catch {
          return url
        }
      }
      return field(input, 'query')
    }
    // What a call acts on comes before any prose the model wrote about it.
    case 'agent':
      return field(input, 'to', 'name', 'scriptPath', 'subagent_type', 'description', 'summary')
    case 'plan':
      return [field(input, 'cron'), field(input, 'prompt')].filter(Boolean).join(' ') || field(input, 'description')
    case 'skill':
      return field(input, 'skill')
    default:
      return field(input, 'command', 'url', 'to', 'cron', 'file_path', 'path', 'query', 'name', 'title', 'description')
  }
}

/** How `fit` cuts: a path keeps its end, a command its start and end, other text its start. */
export type FitMode = 'path' | 'command' | 'text'

/**
 * Cut to `room` characters. A command is never left out: it keeps at least
 * 16, its head and its tail, so what a long line ends with stays in sight.
 * Control and format characters are dropped: a file name or command must not
 * restyle, reorder or rewrite the screen.
 */
export function fit(text: string, room: number, mode: FitMode): string {
  const flat = printable(text.replace(/\s+/g, ' '))
  const space = mode === 'command' ? Math.max(room, 16) : room
  if (space < 4) return ''
  if (flat.length <= space) return flat
  if (mode === 'path') return `…${flat.slice(flat.length - space + 1)}`
  if (mode === 'text') return `${flat.slice(0, space - 1)}…`
  const head = Math.ceil((space - 1) / 2)
  return `${flat.slice(0, head)}…${flat.slice(flat.length - (space - 1 - head))}`
}

const PHRASE: Readonly<Record<Kind, [string, string]>> = {
  read: ['read', 'file'],
  edit: ['edited', 'file'],
  write: ['wrote', 'file'],
  delete: ['deleted with', 'command'],
  shell: ['ran', 'command'],
  search: ['searched', 'pattern'],
  web: ['fetched', 'page'],
  mcp: ['called', 'MCP tool'],
  agent: ['started', 'agent'],
  skill: ['used', 'skill'],
  ask: ['asked', 'question'],
  plan: ['updated', 'plan'],
  other: ['ran', 'tool'],
}

/** A folded group as `read 3 files · searched 2 patterns`, kinds in first-seen order. */
export function groupSummary(calls: ReadonlyArray<{ tool: string; input: unknown }>): { kinds: Kind[]; text: string } {
  const counts = new Map<Kind, number>()
  for (const call of calls) {
    const kind = kindOf(call.tool, call.input)
    counts.set(kind, (counts.get(kind) ?? 0) + 1)
  }
  const parts = [...counts].map(([kind, n]) => {
    const [verb, noun] = PHRASE[kind]
    return `${verb} ${n} ${noun}${n === 1 ? '' : 's'}`
  })
  const text = parts.join(' · ')
  return { kinds: [...counts.keys()], text: text.charAt(0).toUpperCase() + text.slice(1) }
}

